ferido"},{"slug":"tse-2026-270002551273","sq":"270002551273","before":"indeferido com recurso","after":"deferido com recurso"}]$changes$::jsonb;
  changed integer;
  logged integer;
BEGIN
  -- O replay PG17 começa vazio, mas migrations antigas deixam uma coorte
  -- parcial. A flag exclusiva do harness evita classificar isso como drift;
  -- sem a flag, inclusive com zero candidatos, o CAS de 513 reprova.
  IF current_setting('pf.replay', true) = 'true' THEN
    RAISE NOTICE 'situacao_tse_2026: coleta ignorada no replay descartavel';
    RETURN;
  END IF;
  IF jsonb_array_length(cohort) <> 513 OR jsonb_array_length(changes) <> 19 OR
     (SELECT count(*) FROM jsonb_to_recordset(cohort) AS e(outcome text) WHERE e.outcome='encontrado') <> 362 OR
     (SELECT count(*) FROM jsonb_to_recordset(cohort) AS e(outcome text) WHERE e.outcome='indeterminado') <> 151 OR
     (SELECT count(*) FROM public.candidatos WHERE publicavel IS TRUE) <> 513 OR
     (SELECT count(*) FROM jsonb_to_recordset(cohort) AS e(slug text,sq text,method text)
       JOIN public.candidatos c ON c.slug=e.slug AND c.sq_candidato_2026=e.sq AND c.publicavel IS TRUE) <> 513 THEN
    RAISE EXCEPTION 'situacao_tse_2026: identidade/coorte divergente';
  END IF;
  IF (SELECT count(*) FROM jsonb_to_recordset(changes) AS e(slug text,sq text,before text,after text)
      JOIN public.candidatos c ON c.slug=e.slug AND c.sq_candidato_2026=e.sq
      WHERE c.situacao_candidatura=e.before AND c.status='candidato' AND c.publicavel IS TRUE) <> 19 THEN
    RAISE EXCEPTION 'situacao_tse_2026: preimagem de situacao divergente';
  END IF;
  IF EXISTS (SELECT 1 FROM public.coleta_log WHERE execucao='migration:20260924205031') THEN
    RAISE EXCEPTION 'situacao_tse_2026: recibos ja existem';
  END IF;

  -- @write tabela=candidatos ref=migration:20260924205031 campos=situacao_candidatura
  UPDATE public.candidatos c
  SET situacao_candidatura=e.after
  FROM jsonb_to_recordset(changes) AS e(slug text,sq text,before text,after text)
  WHERE c.slug=e.slug AND c.sq_candidato_2026=e.sq
    AND c.situacao_candidatura=e.before
    AND c.status='candidato' AND c.publicavel IS TRUE;
  GET DIAGNOSTICS changed = ROW_COUNT;
  IF changed <> 19 THEN RAISE EXCEPTION 'situacao_tse_2026: updates %, esperado 19',changed; END IF;

  -- @write tabela=coleta_log ref=migration:20260924205031 campos=fonte,escopo,alvo,candidato_id,executado_em,resultado,volume,detalhe,url,execucao,natureza
  INSERT INTO public.coleta_log
    (fonte,escopo,alvo,candidato_id,executado_em,resultado,volume,detalhe,url,execucao,natureza)
  SELECT 'tse-situacao','candidato',c.slug,c.id,
         '2026-09-24T17:22:25.641Z'::timestamptz,
          e.outcome,
          CASE WHEN e.outcome='encontrado' THEN 1 ELSE 0 END,
         jsonb_build_object(
            'ano_eleicao',2026,'sq_candidato',e.sq,'metodo',e.method,
            'escopo','situacao de julgamento no pacote complementar TSE',
            'resource_sha256','86b28861a5ac5ab15c6de590646b916dba8a6134a5c8294534c817ab385a0610',
            'motivo',e.reason,
           'atualizacao_automatica',EXISTS(SELECT 1 FROM jsonb_to_recordset(changes) AS u(slug text,sq text,before text,after text) WHERE u.slug=e.slug),
           'pendencia_terminal',e.slug='tse-2026-190002554290'
         )::text,
         'https://cdn.tse.jus.br/estatistica/sead/odsele/consulta_cand_complementar/consulta_cand_complementar_2026.zip',
         'migration:20260924205031','coleta'
  FROM jsonb_to_recordset(cohort) AS e(slug text,sq text,method text,outcome text,reason text)
  JOIN public.candidatos c ON c.slug=e.slug AND c.sq_candidato_2026=e.sq
  ORDER BY c.slug;
  GET DIAGNOSTICS logged = ROW_COUNT;
  IF logged <> 513 THEN RAISE EXCEPTION 'situacao_tse_2026: recibos %, esperado 513',logged; END IF;
END
$migration$;

COMMIT;
